import { EventEmitter } from "node:events";
class PriceTicker extends EventEmitter {
  set price(next) {
    const prev = this.#price;
    this.#price = next;
    this.emit("price", { prev, next });
  }
}
const ticker = new PriceTicker();
const onPrice = ({ next }) => warn(next);
ticker.on("price", onPrice);
ticker.off("price", onPrice);   // needs the same function reference
